param([Parameter(Mandatory)][string]$Executable,[Parameter(Mandatory)][string]$ProviderExecutable,[Parameter(Mandatory)][string]$ProjectRoot,[Parameter(Mandatory)][string]$ScratchRoot)
$ErrorActionPreference='Stop';$checks=0;$service=$null;$provider=$null
$root=Join-Path $ScratchRoot ('foreground-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null
$env:TEMP=$root;$env:TMP=$root;$env:HIBERNATION_SESSION_KEY='foreground-fixture';$env:HIBERNATION_PRIORITY_KEY='foreground-model-fixture'
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,$Name,[int]$Seconds=25){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 35};try{Api '/api/state'|ConvertTo-Json -Depth 40|Set-Content "$root/timeout.json"}catch{};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$a=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer foreground-fixture'};TimeoutSec=10};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 40 -Compress))};Invoke-RestMethod @a}
function Plan($Items){$text=@{nonce=[Guid]::NewGuid().ToString('N');responses=@($Items)}|ConvertTo-Json -Depth 40;[IO.File]::WriteAllText("$root/provider/plan.next",$text,[Text.UTF8Encoding]::new($false));[IO.File]::Move("$root/provider/plan.next","$root/provider/plan.json",$true)}
function Reply($Text){@{version=1;kind='reply';text=$Text;calls=@();presentation=@{speech=$false;bubble=$true}}}
function Request($Id){(Api '/api/state').jobs.Where({$_.id-eq$Id})[0]}
function Start-Backend{Remove-Item "$root/ready.json" -ErrorAction SilentlyContinue;$script:service=Start-Process $Executable -ArgumentList ('--config "'+$root+'/config.json" --ready-file "'+$root+'/ready.json"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/service.log" -RedirectStandardError "$root/error.log";Wait-For {if($service.HasExited){throw 'fixture exited'};Test-Path "$root/ready.json"} 'backend';$script:origin='http://127.0.0.1:'+((Get-Content "$root/ready.json" -Raw|ConvertFrom-Json).port)}
function Stop-Backend{$null=Api '/api/shutdown' @{};Check ($service.WaitForExit(12000)-and$service.ExitCode-eq0) 'clean process shutdown'}
try{
 $provider=Start-Process $ProviderExecutable -ArgumentList ('"'+$root+'/provider"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/provider.log" -RedirectStandardError "$root/provider-error.log";Wait-For {Test-Path "$root/provider/port"} 'provider';$fixture='http://127.0.0.1:'+(Get-Content "$root/provider/port")
 $cfg=Get-Content "$ProjectRoot/config/example.json" -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot="$root/data";$cfg.characterRoot="$ProjectRoot/character";$cfg.uiRoot="$ProjectRoot/ui";$cfg.pluginRoot=(Join-Path (Split-Path $Executable) plugins);$cfg.plugins=@{};$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=5000;$cfg.maxStartsPerHour=1000;$cfg.profiles+=@{id='fixture';label='Priority fixture';enabled=$true;protocol='chat-completions';origin=$fixture;basePath='/v1';model='fixture-model';credentialEnvironment='HIBERNATION_PRIORITY_KEY';timeoutMs=15000;maxOutputTokens=2048};$cfg|ConvertTo-Json -Depth 40|Set-Content "$root/config.json" -Encoding utf8
 Start-Backend;$null=Api '/api/message' @{request_id='seed';text='有个问题暂时没有回答。'};Wait-For {!(Api '/api/chat').busy} 'seed';$null=Api '/api/model' @{id='fixture'}
 Plan @(@{response=(Reply '过期的后台回答不应出现。');delay_ms=8000},@{response=(Reply '现在先听你说。')});$null=Api '/api/solitude' @{};Wait-For {(Request 'solitude.once').state-eq'running'-and(Test-Path "$root/provider/last-request.json")} 'background inference actually running'
 $before=Api '/api/chat';Check ($before.busy-and$before.can_send) 'background inference leaves foreground input available';$clock=[Diagnostics.Stopwatch]::StartNew();$accepted=Api '/api/message' @{request_id='priority-1';text='先说眼前这件事。'};Check ($accepted.status-eq'queued'-and$clock.ElapsedMilliseconds-lt1000) 'foreground accepts immediately while background yields'
 $again=Api '/api/message' @{request_id='priority-1';text='先说眼前这件事。'};Check $again.duplicate 'accepted foreground request remains idempotent';Wait-For {(Api '/api/chat').messages[-1].text-eq'现在先听你说。'} 'foreground reply' 5;Check ($clock.Elapsed.TotalSeconds-lt5) 'foreground completes without waiting for the eight second provider response';$chat=Api '/api/chat';Check ($chat.can_send-and!$chat.call_failed) 'input becomes available after the foreground result';Check (@($chat.messages|Where-Object {$_.text-eq'过期的后台回答不应出现。'}).Count-eq0) 'cancelled background draft never becomes visible'
 $deferred=Request 'solitude.once';Check ($deferred.state-in@('paused','pending')) 'background cancellation retains a resumable task';Wait-For {$j=Request 'solitude.once';$j.state-eq'pending'-and$j.due_at-gt[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()} 'background deferred until a later idle interval'
 # Persisted foreground-yield ownership must survive pause and restart. A new
 # response is deliberately slow so the operator pauses it before completion.
 Plan @(@{response=(Reply '又一份过期草稿。');delay_ms=8000},@{response=(Reply '暂停后仍接着这句话。');delay_ms=1000});Wait-For {(Request 'solitude.once').state-eq'running'} 'deferred background starts' 15
 $null=Api '/api/message' @{request_id='priority-2';text='再等一下。'};$null=Api '/api/control' @{paused=$true};Wait-For {(Request 'chat').state-eq'paused'} 'foreground paused';Check (!(Api '/api/chat').can_send) 'global pause still blocks input';$count=(Api '/api/chat').messages.Count;Stop-Backend;Start-Backend;Check ((Api '/api/chat').paused-and(Api '/api/chat').messages.Count-eq$count) 'restart retains paused input and transcript'
 Plan @(@{response=(Reply '暂停后仍接着这句话。')});$null=Api '/api/control' @{paused=$false};Wait-For {(Api '/api/chat').messages[-1].text-eq'暂停后仍接着这句话。'} 'foreground resumes after restart';Check (@((Api '/api/chat').messages|Where-Object {$_.text-eq'又一份过期草稿。'}).Count-eq0) 'restart does not publish cancelled background output';Check ((Api '/api/chat').health-eq'ok') 'priority transitions retain healthy storage and journal';Stop-Backend
 @{completed=$true;checks=$checks;root=$root;timestamp=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json|Set-Content "$root/acceptance.json";Write-Output "Foreground priority passed: $checks checks. Evidence: $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}};if($provider){$provider.Refresh();if(!$provider.HasExited){Stop-Process -Id $provider.Id}}}

